def solve(inputs: dict) -> float:
    remainders = inputs['remainders']
    moduli = inputs['moduli']

    # Chinese Remainder Theorem solver
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def mod_inverse(a, m):
        gcd, x, _ = extended_gcd(a % m, m)
        if gcd != 1:
            return None
        return (x % m + m) % m

    x = 0
    M = 1
    for m in moduli:
        M *= m

    for r, m in zip(remainders, moduli):
        Mi = M // m
        yi = mod_inverse(Mi, m)
        x += r * Mi * yi

    x = x % M
    return float(x)

